<?php
require_once __DIR__.'/includes/bootstrap.php';require_manager();$pdo=db();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$product=(int)($_POST['product_id']??0);$stock=(int)($_POST['stock_item_id']??0);$qty=(float)($_POST['quantity_used']??0);
 if($product<1||$stock<1||$qty<=0)$err='Choose a menu item, a stock item and a quantity greater than zero.';
 else try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id FROM recipes WHERE product_id=?');$s->execute([$product]);$recipe=$s->fetchColumn();if(!$recipe){$s=$pdo->prepare('INSERT INTO recipes(product_id) VALUES(?)');$s->execute([$product]);$recipe=$pdo->lastInsertId();}$s=$pdo->prepare('INSERT INTO recipe_items(recipe_id,stock_item_id,quantity_used) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity_used=VALUES(quantity_used)');$s->execute([$recipe,$stock,$qty]);$pdo->commit();$msg='Recipe ingredient saved. Future sales will deduct this quantity per menu item sold.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='Could not save recipe. Check the selected items.';}
}
$products=$pdo->query('SELECT id,name FROM products WHERE is_available=1 ORDER BY name')->fetchAll();$stock=$pdo->query('SELECT id,name,unit FROM stock_items ORDER BY name')->fetchAll();$recipes=$pdo->query('SELECT p.name product_name,si.name stock_name,si.unit,ri.quantity_used FROM recipe_items ri JOIN recipes r ON r.id=ri.recipe_id JOIN products p ON p.id=r.product_id JOIN stock_items si ON si.id=ri.stock_item_id ORDER BY p.name,si.name')->fetchAll();
$pageTitle='Recipe Setup';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?>
<div class="panel"><h2>Connect menu items to ingredients</h2><p class="muted">Example: one Quarter Chicken sale can deduct 1 chicken portion and the required quantities of chips or rice when those ingredients are configured. Add one ingredient at a time.</p>
<?php if(!$products||!$stock):?><div class="alert danger">Add menu products and stock items before setting up recipes.</div><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div><label>Menu item</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div><label>Ingredient / stock item</label><select name="stock_item_id" required><?php foreach($stock as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?> (<?=e($s['unit'])?>)</option><?php endforeach;?></select></div><div><label>Quantity used per menu item sold</label><input type="number" name="quantity_used" min="0.001" step="0.001" required placeholder="e.g. 1"></div><div class="form-action"><button class="btn primary">Save recipe ingredient</button></div></form><?php endif;?></div>
<div class="panel"><h2>Configured recipe ingredients</h2><div class="table-wrap"><table><thead><tr><th>Menu item</th><th>Ingredient</th><th>Quantity per sale</th></tr></thead><tbody><?php foreach($recipes as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['stock_name'])?></td><td><?=number_format($r['quantity_used'],3)?> <?=e($r['unit'])?></td></tr><?php endforeach;?><?php if(!$recipes):?><tr><td colspan="3" class="empty">No recipes configured yet. Stock will not be deducted from meals until recipes are entered.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
